                    RAISE EXCEPTION
                        'MINDATLAS_PLAN01_SOURCE_DRAFT: source_draft_version_id must name save'
                        USING ERRCODE = 'integrity_constraint_violation';
                END IF;
            END IF;
            RETURN NEW;
        END;
